// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        // admissible domain: receiver is not the contract itself (self-transfer would mask the rule)
        vm.assume(receiver != address(c));

        // fund the contract so the low-level transfer succeeds for ANY amount
        vm.deal(address(c), amount);
        uint256 before = receiver.balance;

        // the deployer (this test contract) is the owner of c
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            // rule: the named receiver's balance grew by exactly `amount`
            assertTrue(receiver.balance == before + amount, "receiver must receive exactly amount");
        } catch {
            // reference C, once funded, never reverts for an EOA receiver
            assertTrue(false, "sendTo should succeed for a funded contract");
        }
    }
}
